  "decisions": {
    "selected_poi_ids": [
      "xa001",
      "xa002",
      "xa003",
      "xa004",
      "xa005",
      "xa006",
      "xa007",
      "xa011"
    ],
    "poi_notes": {
      "xa001": "秦始皇帝陵博物院（兵马俑）——世界遗产、推荐游览约4小时，室内/室外混合，雨天适宜但步行强度高。门票信息离线数据未给出，需提前核实和预约。",
      "xa002": "西安城墙——室外为主，推荐时长约3小时，可骑行或步行；雨天/高温条件下适应性为“条件”，注意防晒和降温；门票信息需确认。",
      "xa003": "陕西历史博物馆——室内为主、免费（数据标注票价0.0），推荐约3小时，低体力消耗且雨天适宜，适合安排在高温或降雨时段。",
      "xa004": "大雁塔文化休闲景区——混合型，推荐约2小时，适合作为半天行程或与周边广场活动搭配，门票信息需核实。",
      "xa005": "大唐不夜城——夜间城市地标、步行街与演出，推荐夜晚2.5小时体验，室外为主，雨天适应性为条件。",
      "xa006": "回民街——小吃街、夜游首选，推荐约2小时，适合与大唐不夜城或晚餐安排联合访问，注意高温/雨天影响。",
      "xa007": "华清宫——宫苑与园林，推荐约3小时，混合室内/室外，适合半天行程，门票信息需核实。",
      "xa011": "西安博物院——混合型、推荐约2.5小时，数据标注为免费（票价未知/未标），室内部分适合避暑/避雨。"
    }
  },
  "risks": {
    "risk_days": [
      {
        "date": "2026-08-07",
        "notes": "高温季节（8月）可能影响多个以户外为主的景点（西安城墙、回民街/大唐不夜城在白天热感明显、夜间较好）。兵马俑步行强度高，需注意补水与避暑。雨天会降低户外体验（户外_ratio高的景点标注为'conditional'或'rain_suitability'为'conditional')."
      },
      {
        "date": "2026-08-08",
        "notes": "同上；建议把主要室内博物馆（陕西历史博物馆、西安博物院）安排在白天高温或可能降雨时段。"
      },
      {
        "date": "2026-08-09",
        "notes": "同上；若遇长时间降雨，应把华清宫、骊山等室外强体力项目替换为室内博物馆。"
      }
    ],
    "adjustment_required": true,
    "adjustment_notes": "行程应保留灵活性：优先在高温/降雨天气将陕西历史博物馆、西安博物院等室内景点安排在最热或可能下雨的时间段；将夜间活动（大唐不夜城、回民街）放在晚上以避开白天高温。需提前核实兵马俑与部分景点门票/预约政策，并准备雨具、防晒与充足饮水。"
  },
  "itinerary": {
    "daily_itinerary": [
      {
        "day": 1,
        "attraction_poi_ids": [
          "xa001",
          "xa007",
          "xa005"
        ],
        "notes": "上午安排秦始皇帝陵博物院（约4小时，需提前查票与预约）。下午或傍晚前往华清宫（约3小时，混合型）。晚上体验大唐不夜城夜景与演出（约2.5小时）。"
      },
      {
        "day": 2,
        "attraction_poi_ids": [
          "xa003",
          "xa011",
          "xa004"
        ],
        "notes": "将陕西历史博物馆（室内，约3小时）和西安博物院（约2.5小时）安排在白天高温时段以避暑。傍晚或下午可安排大雁塔文化休闲景区（约2小时）。"
      },
      {
        "day": 3,
        "attraction_poi_ids": [
          "xa002",
          "xa006"
        ],
        "notes": "早晨或傍晚安排西安城墙骑行/漫步（约3小时，以避免中午高温）。行程结束前往回民街体验小吃（约2小时）。若天气不适合户外，可用空余时间补充博物馆参观或购物。"
      }
    ]
  },
  "budget": {
    "feasibility": "possible_with_caveats",
    "budget_notes": "预算5000元（目的地本地花费）对2人、3天的西安行程总体可行，前提是住宿、餐饮与门票选择为中档或节省型。已选景点中陕西历史博物馆与部分博物馆被标注免费，有利于控制成本；但秦始皇帝陵博物院及华清宫等可能需购票并预约，需提前确认票价与预约费用。未包含酒店和餐饮明细，需根据实际选择核算。也未包含城市内交通费（建议使用地铁/网约车），请在最终预算中预留门票、交通、餐饮与纪念品费用。",
    "recommended_total": 4500.0
  },
  "confidence": 0.8
}

